import numpy as np
import pandas as pd
from pandas import Timedelta
from pandas._libs.tslibs.np_datetime import OutOfBoundsTimedelta

def rec(name, value):
    probe(name, value)

results = {}

# 1) to_timedelta float ndarray with errors='coerce'
try:
    v = pd.to_timedelta(np.array([1.5, 1e30]), unit='s', errors='coerce')
    rec('to_timedelta_ndarray_coerce_1', v)
except Exception as e:
    rec('to_timedelta_ndarray_coerce_1_exc', f'{type(e).__name__}: {e}')

# 2) to_timedelta float ndarray containing +/-inf
try:
    v = pd.to_timedelta(np.array([1.0, np.inf]), errors='coerce')
    rec('to_timedelta_ndarray_coerce_inf_pos', v)
except Exception as e:
    rec('to_timedelta_ndarray_coerce_inf_pos_exc', f'{type(e).__name__}: {e}')

try:
    v = pd.to_timedelta(np.array([1.0, -np.inf]), errors='coerce')
    rec('to_timedelta_ndarray_coerce_inf_neg', v)
except Exception as e:
    rec('to_timedelta_ndarray_coerce_inf_neg_exc', f'{type(e).__name__}: {e}')

# 3) Timedelta constructed from kwargs with inf (days)
try:
    v = Timedelta(days=np.inf)
    rec('Timedelta_inf_kwargs_days', v)
except Exception as e:
    rec('Timedelta_inf_kwargs_days_exc', f'{type(e).__name__}: {e}')

# 4) to_datetime errors='coerce' with infinite float in hour field
# Use a small DataFrame similar to the report.
try:
    df = pd.DataFrame({'year':[2000,2000], 'month':[1,1], 'day':[1,1], 'hour':[12.0, np.inf]})
    v = pd.to_datetime(df, errors='coerce')
    rec('to_datetime_df_coerce_inf_hour', v)
except Exception as e:
    rec('to_datetime_df_coerce_inf_hour_exc', f'{type(e).__name__}: {e}')

